mapper.select:
        SELECT edd.*
        FROM sys_enclosure_dictionary_detail AS edd
                 INNER JOIN sys_enclosure_dictionary AS ed ON edd.enclosure_dictionary_id = ed.id
        WHERE ed.bool_delete_enum = 0
          AND edd.bool_delete_enum = 0
          AND ed.STATUS = 1
          AND ed.type = #{type}
          AND ed.NAME = #{name}
          AND ed.label = #{label}
